export type AccentOption = {
  id: string
  label: string
  value: string
}

export type ThemeTokens = {
  background: string
  foreground: string
  surface: string
  border: string
  muted: string
  mutedForeground: string
  primary: string
  primaryForeground: string
  accent: string
  accentForeground: string
  success: string
  warning: string
  danger: string
  info: string
  radius: string
}

export type TenantManifest = {
  tenantId: string
  slug: string
  name: string
  branding: {
    logoUrl: string
    iconUrl?: string
    lightTheme: ThemeTokens
    darkTheme: ThemeTokens
    accentOptions: AccentOption[]
    terminology?: Record<string, string>
  }
  localization: {
    defaultLocale: string
    enabledLocales: string[]
  }
  enabledApps: string[]
  enabledProjectApps: string[]
  enabledAdminModules: string[]
  featureFlags: string[]
  policies: {
    allowSelfSignup: boolean
    requireAdminApproval: boolean
    allowPaidApps: boolean
    allowSecondaryMarket: boolean
    allowPushNotifications: boolean
  }
}

export type Tenant = {
  id: string
  slug: string
  name: string
  status: 'active' | 'suspended' | 'trial'
  usersCount: number
  projectsCount: number
  enabledApps: string[]
  creditBalance: number
  createdAt: string
}
